// One item per meeting. Meetings with neither a body nor (later) notes are
// dropped further down - no content, nothing to classify.
const res = $input.first().json || {};
const rows = Array.isArray(res.results) ? res.results : [];
return rows.map(m => ({ json: {
  meeting_id: String(m.id),
  title: (m.properties && m.properties.hs_meeting_title) || 'HubSpot meeting',
  body: (m.properties && m.properties.hs_meeting_body) || '',
  ts: (m.properties && m.properties.hs_timestamp) || null,
} }));

// Carry the meeting fields forward + the list of associated note ids.
const meeting = $('One item per meeting').item.json;
const res = $json || {};
const ids = Array.isArray(res.results) ? res.results.map(r => String(r.toObjectId)) : [];
return { json: { ...meeting, note_ids: ids } };

const meeting = $('Attach note ids').item.json;
const res = $json || {};
const notes = Array.isArray(res.results) ? res.results.map(r => (r.properties && r.properties.hs_note_body) || '').filter(Boolean) : [];
return { json: { ...meeting, notes } };

const meeting = $('Attach notes').item.json;
const res = $json || {};
const first = Array.isArray(res.results) && res.results.length ? res.results[0] : null;
return { json: { ...meeting, company_id: first ? String(first.toObjectId) : null } };

// Build ONE inbox insert per meeting that actually has content. Same payload
// shape as the Teams watcher, so the Main Pipeline treats it identically;
// source 'hubspot' + a single-shot dedup key mean a meeting can never be
// ingested twice. HTML from HubSpot bodies is stripped to plain text.
const m = $('Attach company id').item.json;
const comp = ($json && $json.properties && $json.properties.name) || '';
const strip = h => String(h || '').replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
const parts = [];
if (m.body) parts.push(strip(m.body));
for (const n of (m.notes || [])) { const t = strip(n); if (t) parts.push(t); }
const text = parts.join('\n\n');
if (!text) return { json: { sql: "SELECT 'skipped - no content' AS note;", skipped: true } };
const e = s => String(s == null ? '' : s).replace(/'/g, "''");
const title = m.title + ' (HubSpot notes)';
const transcript = 'Notes logged in HubSpot for this meeting (no transcript available):\n\n' + text;
const sql =
  "INSERT INTO inbox (source, dedup_key, payload, status) " +
  "SELECT 'hubspot', 'hs:" + e(m.meeting_id) + "', jsonb_build_object(" +
    "'account', COALESCE(" +
      "(SELECT name FROM accounts WHERE lower(name) = lower('" + e(comp) + "') LIMIT 1)," +
      "(SELECT name FROM client_directory WHERE '" + e(comp) + "' ILIKE '%'||name||'%' OR name ILIKE '%'||'" + e(comp) + "'||'%' ORDER BY length(name) DESC LIMIT 1)," +
      "(SELECT name FROM client_directory WHERE '" + e(m.title) + "' ILIKE '%'||name||'%' ORDER BY length(name) DESC LIMIT 1)," +
      "'UNKNOWN')," +
    "'title', '" + e(title) + "'," +
    "'visibility', 'all'," +
    "'external_domains', '[]'::jsonb," +
    "'dedup_key', 'hs:" + e(m.meeting_id) + "'," +
    "'transcript', '" + e(transcript) + "'" +
  "), 'pending' " +
  "ON CONFLICT (dedup_key) DO NOTHING RETURNING id;";
return { json: { sql, skipped: false, title } };
